package com.infosys.carbonfootprint.entity;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.time.*;
@Entity @Table(name="alerts", uniqueConstraints=@UniqueConstraint(columnNames={"user_id","category_id","alertType","alert_month","alert_year"})) @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
public class Alert { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne @JoinColumn(name="user_id",nullable=false) private User user; @ManyToOne @JoinColumn(name="category_id") private Category category; @Enumerated(EnumType.STRING) @Column(nullable=false) private AlertType alertType; @Enumerated(EnumType.STRING) @Column(nullable=false) private AlertSeverity severity; @Column(nullable=false) private String title; @Column(length=1200,nullable=false) private String message; @Column(length=1200) private String recommendation; private Double currentEmission; private Double monthlyLimit; private Double exceededAmount; @Column(name="alert_month",nullable=false) private Integer month; @Column(name="alert_year",nullable=false) private Integer year; @Builder.Default private boolean isRead=false; @Column(nullable=false, columnDefinition="boolean default false") @Builder.Default private boolean resolved=false; @CreationTimestamp private LocalDateTime createdAt; }